checkly:index/alertChannel:AlertChannel.description:
Allows you to define alerting channels for the checks and groups in your account

## Example Usage

<!--Start PulumiCodeChooser -->
```typescript
import * as pulumi from "@pulumi/pulumi";
import * as checkly from "@checkly/pulumi";

// An Email alert channel
const emailAc = new checkly.AlertChannel("email_ac", {
    email: {
        address: "john@example.com",
    },
    sendRecovery: true,
    sendFailure: false,
    sendDegraded: true,
    sslExpiry: true,
    sslExpiryThreshold: 22,
});
// A SMS alert channel
const smsAc = new checkly.AlertChannel("sms_ac", {
    sms: {
        name: "john",
        number: "+5491100001111",
    },
    sendRecovery: true,
    sendFailure: true,
});
// A Slack App alert channel, using the Checkly Slack App
const slackAppAc = new checkly.AlertChannel("slack_app_ac", {slackApp: {
    slackChannels: [
        "#checkly-notifications",
        "@john",
    ],
}});
// A legacy Slack alert channel, using a Slack webhook URL.
// Deprecated: use the slack_app attribute instead.
const slackAc = new checkly.AlertChannel("slack_ac", {slack: {
    channel: "#checkly-notifications",
    url: "https://hooks.slack.com/services/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",
}});
// An Opsgenie alert channel
const opsgenieAc = new checkly.AlertChannel("opsgenie_ac", {opsgenie: {
    name: "opsalerts",
    apiKey: "fookey",
    region: "US",
    priority: "P1",
}});
// A Pagerduty alert channel
const pagerdutyAc = new checkly.AlertChannel("pagerduty_ac", {pagerduty: {
    account: "checkly",
    serviceKey: "key1",
    serviceName: "pdalert",
}});
// A Webhook alert channel
const webhookAc = new checkly.AlertChannel("webhook_ac", {webhook: {
    name: "foo",
    method: "GET",
    template: "footemplate",
    url: "https://example.com/foo",
    webhookSecret: "foosecret",
}});
// A FireHydrant alert channel integration
const firehydrantAc = new checkly.AlertChannel("firehydrant_ac", {webhook: {
    name: "firehydrant",
    method: "POST",
    template: `{
  \\"event\\": \\"{{ALERT_TITLE}}\\",
  \\"link\\": \\"{{RESULT_LINK}}\\",
  \\"check_id\\": \\"{{CHECK_ID}}\\",
  \\"check_type\\": \\"{{CHECK_TYPE}}\\",
  \\"alert_type\\": \\"{{ALERT_TYPE}}\\",
  \\"started_at\\": \\"{{STARTED_AT}}\\",
  \\"check_result_id\\": \\"{{CHECK_RESULT_ID}}\\"
}
`,
    url: "https://app.firehydrant.io/integrations/alerting/webhooks/2/checkly",
    webhookType: "WEBHOOK_FIREHYDRANT",
}});
// A Rootly alert channel — In-App Routing mode.
// Alerts are sent to Rootly and routed internally via Rootly Alert Routes.
const rootlyInappAc = new checkly.AlertChannel("rootly_inapp_ac", {
    webhook: {
        name: "Rootly (In-App Routing)",
        method: "POST",
        url: "https://webhooks.rootly.com/webhooks/incoming/checkly_webhooks",
        webhookSecret: "<rootly-webhook-secret>",
        webhookType: "WEBHOOK_ROOTLY",
        template: `{
  \\"alert_type\\": \\"{{ALERT_TYPE}}\\",
  \\"check_id\\": \\"{{CHECK_ID}}\\",
  \\"check_result_id\\": \\"{{CHECK_RESULT_ID}}\\",
  \\"check_name\\": \\"{{CHECK_NAME}}\\",
  \\"alert_title\\": \\"{{ALERT_TITLE}}\\",
  \\"started_at\\": \\"{{STARTED_AT}}\\",
  \\"link\\": \\"{{RESULT_LINK}}\\"
}
`,
    },
    sendRecovery: true,
    sendFailure: true,
});
// A Rootly alert channel — Direct Routing mode.
// Alerts are routed directly to a specific Rootly target via the URL.
// Type is one of: Service, Group (for Teams), EscalationPolicy, Functionality.
// The target ID can be found in the Rootly UI for the chosen resource.
const rootlyDirectAc = new checkly.AlertChannel("rootly_direct_ac", {
    webhook: {
        name: "Rootly (Direct Routing)",
        method: "POST",
        url: "https://webhooks.rootly.com/webhooks/incoming/checkly_webhooks/notify/EscalationPolicy/<rootly-escalation-policy-id>",
        webhookSecret: "<rootly-webhook-secret>",
        webhookType: "WEBHOOK_ROOTLY",
        template: `{
  \\"alert_type\\": \\"{{ALERT_TYPE}}\\",
  \\"check_id\\": \\"{{CHECK_ID}}\\",
  \\"check_result_id\\": \\"{{CHECK_RESULT_ID}}\\",
  \\"check_name\\": \\"{{CHECK_NAME}}\\",
  \\"alert_title\\": \\"{{ALERT_TITLE}}\\",
  \\"started_at\\": \\"{{STARTED_AT}}\\",
  \\"link\\": \\"{{RESULT_LINK}}\\"
}
`,
    },
    sendRecovery: true,
    sendFailure: true,
});
// Connecting the alert channel to a check
const exampleCheck = new checkly.ApiCheck("example_check", {
    name: "Example check",
    request: {
        url: "https://api.example.com/",
    },
    alertChannelSubscriptions: [
        {
            channelId: emailAc.id,
            activated: true,
        },
        {
            channelId: smsAc.id,
            activated: true,
        },
    ],
});
