		_, err = checkly.NewAlertChannel(ctx, "slack_app_ac", &checkly.AlertChannelArgs{
			SlackApp: &checkly.AlertChannelSlackAppArgs{
				SlackChannels: pulumi.StringArray{
					pulumi.String("#checkly-notifications"),
					pulumi.String("@john"),
				},
			},
		})
		if err != nil {
			return err
		}
