		if err != nil {
			return err
		}
		// A Webhook alert channel
		_, err = checkly.NewAlertChannel(ctx, "webhook_ac", &checkly.AlertChannelArgs{
			Webhook: &checkly.AlertChannelWebhookArgs{
				Name:          pulumi.String("foo"),
				Method:        pulumi.String("GET"),
