    name: "Example DNS monitor",
    activated: true,
    frequency: 2,
    useGlobalAlertSettings: true,
    locations: ["eu-west-1"],
    request: {
        recordType: "A",
        query: "welcome.checklyhq.com",
        nameServer: {
            host: "1.1.1.1",
            port: 53,
