```typescript
import * as pulumi from "@pulumi/pulumi";
import * as checkly from "@checkly/pulumi";

// Basic TCP monitor
const example_tcp_monitor = new checkly.TcpMonitor("example-tcp-monitor", {
    name: "Example TCP monitor",
    activated: true,
    shouldFail: false,
    frequency: 1,
    useGlobalAlertSettings: true,
    locations: ["us-west-1"],
    request: {
        hostname: "api.checklyhq.com",
        port: 80,
    },
});
// A more complex example using assertions and setting alerts
const example_tcp_monitor_2 = new checkly.TcpMonitor("example-tcp-monitor-2", {
    name: "Example TCP monitor 2",
    activated: true,
    shouldFail: true,
    frequency: 1,
    degradedResponseTime: 4000,
    maxResponseTime: 5000,
    locations: [
        "us-west-1",
        "ap-northeast-1",
        "ap-south-1",
    ],
    alertSettings: {
        escalationType: "RUN_BASED",
        runBasedEscalation: {
            failedRunThreshold: 1,
        },
        reminders: {
            amount: 1,
        },
    },
    retryStrategy: {
        type: "FIXED",
        baseBackoffSeconds: 60,
        maxDurationSeconds: 600,
        maxRetries: 3,
        sameRegion: false,
    },
    request: {
        hostname: "api.checklyhq.com",
        port: 80,
        data: "hello",
        assertions: [
            {
                source: "RESPONSE_DATA",
                property: "",
                comparison: "CONTAINS",
                target: "welcome",
            },
            {
                source: "RESPONSE_TIME",
                property: "",
                comparison: "LESS_THAN",
                target: "2000",
            },
        ],
    },
});
