Traceroute monitors trace the network path to a host and measure per-hop latency and packet loss.

## Example Usage

<!--Start PulumiCodeChooser -->
```typescript
import * as pulumi from "@pulumi/pulumi";
import * as checkly from "@checkly/pulumi";

// Basic traceroute monitor
const example_traceroute_monitor = new checkly.TracerouteMonitor("example-traceroute-monitor", {
    name: "Example traceroute monitor",
    activated: true,
    frequency: 1,
    useGlobalAlertSettings: true,
    locations: ["us-west-1"],
    request: {
        url: "api.checklyhq.com",
    },
});
// A more complex example tuning the trace and adding assertions
const example_traceroute_monitor_2 = new checkly.TracerouteMonitor("example-traceroute-monitor-2", {
    name: "Example traceroute monitor 2",
    activated: true,
    frequency: 5,
    locations: [
        "us-west-1",
        "ap-northeast-1",
    ],
    alertSettings: {
        escalationType: "RUN_BASED",
        runBasedEscalation: {
            failedRunThreshold: 1,
        },
        reminders: {
            amount: 1,
        },
    },
    request: {
        url: "api.checklyhq.com",
        protocol: "ICMP",
        ipFamily: "IPv4",
        maxHops: 30,
        maxUnknownHops: 15,
        ptrLookup: true,
        timeout: 10,
        assertions: [
            {
                source: "PACKET_LOSS",
                property: "",
                comparison: "LESS_THAN",
                target: "10",
            },
            {
                source: "RESPONSE_TIME",
                property: "avg",
                comparison: "LESS_THAN",
                target: "800",
            },
        ],
    },
});
